COMMAND.ACTION:
case "${enc}" in

  7) echo "% Type 7 passwords are not supported; use password 0 <text> or password cipher <block>"; false ;;

  cipher) tertoos-cli candidate set mpls/ldp/${ldpvrf}/af/${ldpafi}/neighbor/${ldpnbr}/password "cipher:${secret}" ;;

  *) tertoos-cli candidate set mpls/ldp/${ldpvrf}/af/${ldpafi}/neighbor/${ldpnbr}/password "${secret}" ;;

esac
